<div class="customer-modal-backdrop" role="presentation"><section class="customer-modal employee-edit-modal" role="dialog" aria-modal="true" aria-labelledby="loan-edit-title"><div class="customer-modal-header"><div><span class="modal-eyebrow">Staff loan</span><h2 id="loan-edit-title">Edit Employee Loan</h2><span class="modal-code"><?= e($loanEdit['employee_code']) ?></span></div><a class="customer-modal-close" href="index.php?page=admin&amp;section=employees-loans" aria-label="Close">&times;</a></div><div class="customer-modal-body"><?php if($errors): ?><div class="alert alert-danger"><?php foreach($errors as $error): ?><div><?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><form method="post" action="index.php?page=admin&amp;section=employees-loans"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="loan_id" value="<?= (int)$loanEdit['id'] ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Employee *</label><select class="form-select" name="employee_id" required><?php foreach($options as $option): ?><option value="<?= (int)$option['id'] ?>" <?= (int)$option['id']===(int)$loanEdit['employee_id']?'selected':'' ?>><?= e($option['name'].' ('.$option['employee_code'].')') ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Loan Date *</label><input class="form-control" type="date" name="loan_date" value="<?= e($loanEdit['loan_date']) ?>" required></div><div class="col-md-6"><label class="form-label">Amount *</label><input class="form-control" type="number" name="amount" min=".01" step=".01" value="<?= e((string)$loanEdit['amount']) ?>" required></div><div class="col-md-6"><label class="form-label">Status</label><select class="form-select" name="status"><option value="active" <?= $loanEdit['status']==='active'?'selected':'' ?>>Active</option><option value="settled" <?= $loanEdit['status']==='settled'?'selected':'' ?>>Settled</option></select></div><div class="col-12"><label class="form-label">Reason</label><input class="form-control" name="reason" value="<?= e($loanEdit['reason']??'') ?>"></div></div><div class="customer-modal-footer px-0 pb-0"><a class="btn btn-light" href="index.php?page=admin&amp;section=employees-loans">Cancel</a><button class="btn btn-primary" type="submit">Update Loan</button></div></form></div></section></div>
